import { Component, OnInit } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { Medicament } from 'src/app/models/Medicament';
import { FournisseurService } from 'src/app/services/fournisseur.service';
import { CommandeService } from 'src/app/services/commande.service';

@Component({
  selector: 'app-medicament-list',
  templateUrl: './medicament-list.component.html',
  styleUrls: ['./medicament-list.component.css']
})
export class MedicamentListComponent implements OnInit {
  medicaments: Medicament[] = [];  // Liste des médicaments du fournisseur
  fournisseurId: number = 0;  // Identifiant du fournisseur
  selectedMedicaments: { medicamentId: number, quantite: number }[] = [];  // Liste des médicaments sélectionnés pour la commande

  constructor(
    private fournisseurService: FournisseurService,
    private route: ActivatedRoute,
    private commandeService: CommandeService
  ) {}

  ngOnInit(): void {
    // Récupérer l'identifiant du fournisseur depuis l'URL
    this.fournisseurId = Number(this.route.snapshot.paramMap.get('id'));
    if (this.fournisseurId) {
      this.getMedicamentsByFournisseur(this.fournisseurId);
    }
  }

  // Récupérer les médicaments du fournisseur
  getMedicamentsByFournisseur(idFournisseur: number): void {
    this.fournisseurService.getMedicamentsByFournisseur(idFournisseur).subscribe(
      data => {
        this.medicaments = data || [];
      },
      error => {
        console.error('Erreur lors de la récupération des médicaments', error);
        this.medicaments = [];
      }
    );
  }

  // Mettre à jour l'état de la quantité demandée et vérifier si elle dépasse le stock
  onQuantityChange(medicament: Medicament): void {
    if (medicament.quantiteCommande > medicament.quantite) {
      medicament.erreur = true;  // Afficher l'erreur si la quantité demandée dépasse le stock
    } else {
      medicament.erreur = false;  // Réinitialiser l'erreur si la quantité est valide
    }
  }

  // Ajouter le médicament et la quantité sélectionnée à la commande
  addToSelection(medicament: Medicament): void {
    // Si la quantité est valide (non négative et inférieure ou égale au stock)
    if (medicament.quantiteCommande > 0 && medicament.quantiteCommande <= medicament.quantite) {
      const existing = this.selectedMedicaments.find(item => item.medicamentId === medicament.idmedicament);
      if (existing) {
        existing.quantite = medicament.quantiteCommande;  // Mettre à jour la quantité si déjà sélectionné
      } else {
        this.selectedMedicaments.push({
          medicamentId: medicament.idmedicament,
          quantite: medicament.quantiteCommande
        });
      }
    }
  }

  // Passer la commande
  passerCommande(): void {
    if (this.selectedMedicaments.length === 0) return;  // Si aucune sélection, ne pas passer la commande

    const commande = {
      fournisseurId: this.fournisseurId,
      status: 'Encours',
      medicaments: this.selectedMedicaments
    };

    this.commandeService.passerCommande(commande).subscribe(
      response => {
        console.log('Commande passée avec succès', response);
        alert('Commande passée avec succès !');
        this.selectedMedicaments = []; // Réinitialiser la sélection après la commande
      },
      error => {
        console.error('Erreur lors de la commande', error);
        alert('Erreur lors de la commande.');
      }
    );
  }
}
